import{z as B,x as A,o as e,c as d,q as s,j as o,D as E,d as t,s as l,S as r,b as n}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"季节性与日历异象","description":"","frontmatter":{"title":"季节性与日历异象","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/seasonality-anomalies.md","filePath":"quant/seasonality-anomalies.md","lastUpdated":1791063341000}'),p={name:"quant/seasonality-anomalies.md"};function m(h,a,u,c,f,C){const i=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=s('<h1 id="季节性与日历异象" tabindex="-1">季节性与日历异象 <a class="header-anchor" href="#季节性与日历异象" aria-label="Permalink to &quot;季节性与日历异象&quot;">​</a></h1><div class="epigraph"><p>日历把交易日切成假日、月初、年末窗口；其中一些均值差异在统计上反复出现，经济上却往往是样本、微观结构与税收窗口，而不是可无限加杠杆的第三因子。</p><footer>—— Lakonishok and Smidt, Are Seasonal Anomalies Real? A Ninety-Year Perspective, Review of Financial Studies, 1988</footer></div><p><a href="/quant/factor-timing-feasibility">上一课</a>的择时用估值与宏观状态。季节性的缺口是<strong>用日历当信号</strong>：一月、月末、假期、Sell in May。主干 <a href="/quant/calendar-overnight">日历效应与隔夜</a> 已写周末、隔夜与制度时钟。本课只放策略地图：哪些日历效应还像可交易边缘，哪些已被费用与拥挤吃掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lakonishok–Smidt 用很长样本问：一月效应、周末效应是否经得起子样本。许多「日历 alpha」在发现后衰减，或只存在于小盘、低价、不可交易的一端。问题是识别：效应来自风险（假日窗口的信息到达）、来自微观结构（收盘拍卖、窗口粉饰）、还是来自税收与基金考核日。Heston–Sadka 的截面季节性（同月动量）与指数层面的 Sell in May（Bouman–Jacobsen）不是同一个对象，不能收成一个「日历因子」去和 HML 做马赛克。</p><p><span class="marginnote">术语翻译：「一月效应」就是每年 1 月小盘股与上年输家系统性强于大盘的历史规律，主流解释是 12 月的税收亏损卖出与窗口粉饰在新年初反转。注意它是截面效应——某类股票相对另一类，不是「1 月大盘必涨」。</span></p><p>与因子择时：日历信号的广度同样接近 1（对给定市场每年就那几次）。IR 必须按事件数而不是按交易日数来算。</p><p><span class="marginnote">数字实例：某日历策略一年只出手 6 次、每次持有 2 天。按日历算它「95% 时间空仓」，若把 250 个交易日的零收益混进年化夏普，年化 1.5 的事件级 IR 会被稀释成 0.2 上下——检验与定仓都要按事件聚集，而不是按交易日摊平。</span></p><h3 id="隔夜不是季节性" tabindex="-1">隔夜不是季节性 <a class="header-anchor" href="#隔夜不是季节性" aria-label="Permalink to &quot;隔夜不是季节性&quot;">​</a></h3><p>隔夜溢价是交易时段切分，见日历课。把它加进「月初效应」会重复计数。策略若声称吃季节性，应排除隔夜与开盘拍卖的冲击模型，否则赚的是微观结构，应归入执行课。</p><p><span class="marginnote">窗口粉饰与税收损失卖出能制造年末到年初的截面，但可预测部分往往被借券与冲击抵消。回测用收盘价在 12 月 31 日调仓，通常不可执行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单：周末/假日、月初月末、财年与税收窗、商品与天气季节（那是曲线，不是股票日历）。检验：子样本、发表前后、市值分层、成本后。事件研究式标准误，见 <a href="/quant/event-study">事件研究</a>。若只在小盘一端显著，容量按小盘算，不要按指数期货名义算。</p>',13)),(e(),o(r,null,{default:E(()=>[l(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Hyp%5B%22%E5%80%99%E9%80%89%E6%97%A5%E5%8E%86%E6%95%88%E5%BA%94%22%5D%20--%3E%20Sub%5B%22%E5%AD%90%E6%A0%B7%E6%9C%AC%3A%20%E5%8F%91%E7%8E%B0%E5%89%8D%E5%90%8E%E5%88%86%E6%AE%B5%22%5D%0A%20%20Sub%20--%3E%20Cap%7B%22%E5%B8%82%E5%80%BC%E5%88%86%E5%B1%82%E5%90%8E%E4%BB%8D%E6%98%BE%E8%91%97%3F%22%7D%0A%20%20Cap%20--%3E%7C%E5%8F%AA%E5%89%A9%E5%B0%8F%E7%9B%98%7C%20CapS%5B%22%E5%AE%B9%E9%87%8F%E6%8C%89%E5%B0%8F%E7%9B%98%E5%8F%A3%E5%BE%84%E7%AE%97%22%5D%0A%20%20Cap%20--%3E%7C%E5%85%A8%E5%9F%9F%E6%98%BE%E8%91%97%7C%20Cost%5B%22%E6%88%90%E6%9C%AC%E5%90%8E%3A%20%E5%80%9F%E5%88%B8%E4%B8%8E%E5%86%B2%E5%87%BB%22%5D%0A%20%20Cost%20--%3E%20EV%5B%22%E6%8C%89%E4%BA%8B%E4%BB%B6%E6%95%B0%E8%81%9A%E9%9B%86%E7%AE%97%20IR%20%E4%B8%8E%E6%A0%87%E5%87%86%E8%AF%AF%22%5D%0A%20%20EV%20--%3E%20Size%7B%22%E4%B8%80%E5%B9%B4%E5%8F%AA%E6%9C%89%E5%87%A0%E6%AC%A1%E5%87%BA%E6%89%8B%22%7D%0A%20%20Size%20--%3E%20Sizing%5B%22%E4%BB%93%E4%BD%8D%E6%8C%89%E5%8D%95%E4%BA%8B%E4%BB%B6%E9%A3%8E%E9%99%A9%E5%AE%9A%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"制度时钟集中了再平衡、考核与信息发布，需求在特定日子倾斜。若倾斜可被灵活资本无成本抵消，效应消失；若必须在收盘拍卖完成（指数、基金），价格压力可重复，那是后课被动流的亲戚，不是神秘月度魔法。",-1)),(e(),o(r,null,{default:E(()=>[l(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Cal%5B%22%E6%97%A5%E5%8E%86%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20Risk%5B%22%E9%A3%8E%E9%99%A9%E4%B8%8E%E4%BF%A1%E6%81%AF%E5%88%B0%E8%BE%BE%22%5D%0A%20%20Cal%20--%3E%20Micro%5B%22%E6%8B%8D%E5%8D%96%20%E7%B2%89%E9%A5%B0%20%E7%A8%8E%E6%94%B6%22%5D%0A%20%20Micro%20--%3E%20Press%5B%22%E5%8F%AF%E9%87%8D%E5%A4%8D%E7%9A%84%E4%BB%B7%E6%A0%BC%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20Risk%20--%3E%20Weak%5B%22%E5%8F%91%E8%A1%A8%E5%90%8E%E5%B8%B8%E8%A1%B0%E5%87%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把占星或农历叙事当因子。加密与 24 小时市场的「日历」要重写，不能抄美股周末效应。后课财报期是公司事件簇，不是同一张月度虚拟变量。</p><p><span class="marginnote">常见误区：初学者容易把「统计显著」当成「可交易」。一个只在低价小盘股上显著的月末效应，单边冲击成本可能就有几十个 bp，比效应本身还大；论文回测用的收盘价你也未必拿得到——检验时面对的是纸面价格，交易时面对的是「必须有人在对面」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>季节性要按事件数检验，发表后多数衰减。</li><li>制度窗口的价格压力与「一月魔法」分开。</li><li>隔夜、拍卖不要算进季节性 alpha。</li><li>出处：Lakonishok and Smidt, <em>RFS</em>, 1988；Bouman and Jacobsen, <em>AER</em>, 2002；截面季节见 Heston and Sadka。</li></ul>',5))])}const _=B(p,[["render",m]]);export{S as __pageData,_ as default};
